SELECT DISTINCT major, college FROM course_catalog cc
JOIN (
  SELECT DISTINCT major FROM course_catalog WHERE major IN (
    SELECT DISTINCT subject_meta_major FROM (
      SELECT json_extract(properties, '$.subject_meta.discipline') AS discipline,
             json_extract(properties, '$.subject_meta.type') AS type
      FROM edges WHERE discipline = 'CivilEnv'
    )
  )
) sub ON cc.major = sub.major

